namespace sv_81994650865040ea903e6c0aa50054d2.Services;

public sealed record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomato sauce.", 30),
            new(2, "Risotto alla Milanese", "Creamy saffron-infused Arborio rice finished with Parmigiano-Reggiano.", 45),
            new(3, "Tiramisu", "Layered espresso-soaked ladyfingers with mascarpone cream and cocoa.", 40),
            new(4, "Pasta Carbonara", "Spaghetti tossed with guanciale, egg yolk, Pecorino Romano, and black pepper.", 25),
        },
        [2] = new List<Recipe>
        {
            new(5, "Chicken Tikka Masala", "Tandoori-spiced chicken in a rich tomato and cream sauce.", 50),
            new(6, "Palak Paneer", "Fresh spinach purée with cubes of paneer cheese and aromatic spices.", 35),
            new(7, "Biryani", "Fragrant basmati rice layered with marinated meat, saffron, and fried onions.", 60),
            new(8, "Samosa", "Crispy pastry filled with spiced potatoes, peas, and cumin.", 45),
        },
        [3] = new List<Recipe>
        {
            new(9, "Sushi Rolls", "Vinegared rice with fresh fish, avocado, and nori seaweed.", 50),
            new(10, "Ramen", "Rich pork-bone broth with wheat noodles, chashu pork, and a soft-boiled egg.", 120),
            new(11, "Tempura", "Lightly battered and deep-fried shrimp and seasonal vegetables.", 30),
            new(12, "Miso Soup", "Dashi broth with fermented soybean paste, tofu, and wakame seaweed.", 15),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

@using sv_81994650865040ea903e6c0aa50054d2.Services

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<div class="mb-3">
    <a href="/recipes/1?sort=@Sort" class="btn btn-outline-primary me-1 @(CuisineId == 1 ? "active" : "")">Italian</a>
    <a href="/recipes/2?sort=@Sort" class="btn btn-outline-primary me-1 @(CuisineId == 2 ? "active" : "")">Indian</a>
    <a href="/recipes/3?sort=@Sort" class="btn btn-outline-primary me-1 @(CuisineId == 3 ? "active" : "")">Japanese</a>
</div>

<div class="mb-3">
    <label class="form-label me-2 fw-bold">Sort by:</label>
    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm btn-outline-secondary me-1 @(EffectiveSort == "newest" ? "active" : "")">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm btn-outline-secondary me-1 @(EffectiveSort == "popular" ? "active" : "")">Popular</a>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center" role="alert">
        <span class="me-auto">@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _isLoading)
{
    <p><em>Loading recipes…</em></p>
}
else if (_recipes is not null)
{
    @if (_isLoading)
    {
        <div class="text-muted mb-2"><small><em>Refreshing…</em></small></div>
    }

    <div class="row">
        @foreach (var recipe in SortedRecipes)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-muted">
                        Prep time: @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>

    @if (_recipes.Count == 0)
    {
        <p class="text-muted">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery] public string? Sort { get; set; }

    private string EffectiveSort => string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
        ? "popular"
        : "newest";

    private List<Recipe>? _recipes;
    private bool _isLoading;
    private string? _errorMessage;
    private int _loadedCuisineId;

    private readonly CancellationTokenSource _disposeCts = new();
    private CancellationTokenSource? _loadCts;

    private IEnumerable<Recipe> SortedRecipes => EffectiveSort == "popular"
        ? _recipes!.OrderBy(r => r.PrepTimeMinutes)
        : _recipes!.OrderByDescending(r => r.Id);

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId)
            return;

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);

        _isLoading = true;
        _errorMessage = null;
        _loadedCuisineId = CuisineId;
        var cuisineId = CuisineId;
        var token = _loadCts.Token;

        try
        {
            var recipes = await RecipeService.GetByCuisineAsync(cuisineId, token);
            token.ThrowIfCancellationRequested();
            _recipes = recipes;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Load was superseded or component disposed — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task RetryAsync()
    {
        _loadedCuisineId = 0;
        await LoadRecipesAsync();
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

